 let dark=document.documentElement.dataset.theme==='dark';
 const setTheme=value=>{dark=value;grid.material.opacity=dark?.15:.45;for(const c of ant.children)if(c.geometry?.type==='CylinderGeometry')c.material.color.set(dark?0xe4eee4:0x253c34);};
 const resize=()=>{const {width,height}=host.getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();};new ResizeObserver(resize).observe(host);resize();let alive=true;const frame=()=>{if(!alive)return;requestAnimationFrame(frame);controls.update();if(needsPick&&pointerLocation&&!presses.size){needsPick=false;inspectAt(pointerLocation.x,pointerLocation.y);}const pn=new T.Vector3(0,0,-1).project(camera),po=new T.Vector3(0,0,0).project(camera);document.querySelector(".orientation svg").style.transform="rotate("+(Math.atan2(pn.x-po.x,pn.y-po.y)*180/Math.PI)+"deg)";renderer.render(scene,camera);};frame();
 return {update(m,base){needsPick=!!pointerLocation;dispose(group);const reference=gainReference(m,base,m.s.dbiReference);probeGainOffset=m.s.dbiReference?m.gain-reference:0;currentMesh=makeSurface(m,false,reference);drawReference(m,reference);group.add(currentMesh);drawAntenna(m);for(const support of m.supports||[]){const scale=4/Math.max(m.s.length,m.s.height*1.2,299.792458/m.s.freq*.6),boom=new T.Line(new T.BufferGeometry().setFromPoints(support.map(p=>new T.Vector3(p[0]*scale,p[2]*scale,-p[1]*scale))),new T.LineBasicMaterial({color:0x899c8a,transparent:true,depthTest:false}));boom.renderOrder=5;ant.add(boom);}setTheme(dark);dispose(comparison);if(base)comparison.add(makeSurface(base,true,m.s.dbiReference?reference:base.gain,m.s.dbiReference?m.s.range:base.s.range));grid.visible=m.s.ground!=='free'&&document.querySelector('#show-grid').checked;},capture(){const before=dark,background=scene.background,oldSize=renderer.getSize(new T.Vector2()),oldAspect=camera.aspect;renderer.setSize(960,760,false);camera.aspect=960/760;camera.updateProjectionMatrix();scene.background=new T.Color('#f6f7f3');setTheme(false);renderer.render(scene,camera);const image=renderer.domElement.toDataURL('image/png');scene.background=background;setTheme(before);renderer.setSize(oldSize.x,oldSize.y,false);camera.aspect=oldAspect;camera.updateProjectionMatrix();renderer.render(scene,camera);return image;},setTheme,inspectAt,setProbe(az,el,relative,visible=true,hitPoint=null){probeGroup.visible=visible;if(!visible)return;const a=az*Math.PI/180,e=el*Math.PI/180,r=Math.max(.08,4.8*Math.max(0,1+(relative+probeGainOffset)/Number(document.querySelector('#range').value))),direction=new T.Vector3(Math.cos(e)*Math.sin(a),Math.sin(e),-Math.cos(e)*Math.cos(a));if(hitPoint)probeDot.position.set(hitPoint.x,hitPoint.y,hitPoint.z);else probeDot.position.copy(direction).multiplyScalar(r);const p=direction.multiplyScalar(5.3);probeRay.geometry.dispose();probeRay.geometry=new T.BufferGeometry().setFromPoints([new T.Vector3(),p]);probeRay.computeLineDistances();},setWireframe(v){if(currentMesh)currentMesh.material.wireframe=v;},setAntenna(v){ant.visible=v;},setGrid(v){grid.visible=v;},setRotation(v){controls.autoRotate=v;},view(v){controls.target.set(0,v==='top'?0:1,0);camera.position.set(...(v==='top'?[0,17,.001]:v==='side'?[0,1,18]:[10,7,12]));controls.update();},destroy(){alive=false;controls.dispose();renderer.dispose();}};
